import { useEffect, useMemo, useRef, useState } from 'react';
import { apiFetch } from './api';
import { useAuth } from './AuthContext';
// The planner is one self-contained page (its own styles, its own drag code), generated by
// bluewater-labor-costing/src/mold_planner.cjs. It runs in a frame so none of its CSS or
// print rules can touch the rest of B.O.S.S.
import page from './moldPlanner/planner.html?raw';
import plan from './moldPlanner/plan.json';

// One shared plan. The page in the frame cannot call the API itself (the token and the demo
// and 401 handling live in apiFetch), so it reaches the server through this bridge, which it
// finds at window.parent.__p27bridge. Contract: BACKEND_MOLD_PLAN_BRIEF.md.
// Until the backend has /api/mold-plan the GET answers 404, get() reports 'off', and the
// planner keeps saving in the browser exactly as it did before.
function makeBridge(username) {
  const shape = (j) => ({ data: j.data, version: j.version, updated_by: j.updated_by, updated_at: j.updated_at });
  return {
    user: username || '',
    async get(since) {
      try {
        const r = await apiFetch(`/api/mold-plan${since ? `?since=${since}` : ''}`);
        if (r.status === 404 || r.status === 403) return { status: 'off' };
        if (!r.ok) return { status: 'error' };
        const j = await r.json();
        if (j.unchanged) return { status: 'same', version: j.version };
        if (!j.data) return { status: 'none' };
        return { status: 'ok', ...shape(j) };
      } catch { return { status: 'error' }; }
    },
    async put(data, baseVersion) {
      try {
        const r = await apiFetch('/api/mold-plan', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ data, base_version: baseVersion }),
        });
        if (r.status === 409) return { status: 'conflict', ...shape(await r.json()) };
        if (!r.ok) return { status: 'error' };
        const j = await r.json();
        if (typeof j.version !== 'number') return { status: 'error' };   // e.g. the demo account's faked write
        return { status: 'ok', version: j.version, updated_by: j.updated_by, updated_at: j.updated_at };
      } catch { return { status: 'error' }; }
    },
  };
}

export default function MoldPlanner() {
  const { user } = useAuth();
  const [names, setNames] = useState(null);   // boat_id -> customer; null while loading
  const [height, setHeight] = useState(620);
  const frame = useRef(null);

  // Set during render, not in an effect: it has to exist before the frame's script runs.
  useMemo(() => { window.__p27bridge = makeBridge(user?.username); }, [user?.username]);
  useEffect(() => () => { delete window.__p27bridge; }, []);

  // Customer names for the bars (the bundled first-pass plan carries hull numbers only,
  // because the app bundle is public). If it fails the planner still opens.
  useEffect(() => {
    let live = true;
    apiFetch('/api/boats')
      .then(r => (r.ok ? r.json() : []))
      .then(list => {
        if (!live) return;
        const m = {};
        for (const b of Array.isArray(list) ? list : []) if (b?.boat_id) m[b.boat_id] = b.customer_name || b.customer || '';
        setNames(m);
      })
      .catch(() => { if (live) setNames({}); });
    return () => { live = false; };
  }, []);

  // Fill the window below the tab bar.
  useEffect(() => {
    const fit = () => {
      if (!frame.current) return;
      const top = frame.current.getBoundingClientRect().top;
      setHeight(Math.max(480, Math.round(window.innerHeight - top - 14)));
    };
    fit();
    window.addEventListener('resize', fit);
    return () => window.removeEventListener('resize', fit);
  }, [names]);

  const doc = useMemo(() => {
    if (!names) return null;
    const data = { ...plan, boats: plan.boats.map(b => ({ ...b, cust: names[b.id] || b.cust || '' })) };
    return page.replace('/*DATA*/null', () => JSON.stringify(data).replace(/</g, '\\u003c'));
  }, [names]);

  if (!doc) return <div className="loading">Loading…</div>;
  return (
    <iframe
      ref={frame}
      title="Mold Planner"
      srcDoc={doc}
      style={{ display: 'block', width: '100%', height, border: 0 }}
    />
  );
}
